INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmux0kdc600c7jh3b1rq1qgm1','Registry milestone: 400+ incidents archived','The archive crossed 400 mirror-verified incidents this month. Thanks to every researcher who filed a responsible disclosure.','GadaLuBau',1,'2026-10-06 18:30:14.406','2026-10-06 18:30:14.406');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmux0kdc600c8jh3bfddfzu6c','New special-archive filter live','Special archives now group incidents by domain pattern (*.gov.*, *.go.*, *.ac.*, *.edu.*). Browse them under Archive Special.','GadaLuBau',0,'2026-10-06 18:30:14.406','2026-10-06 18:30:14.406');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmux0kdc600c9jh3b8r5u5kwu','On-hold verification window updated','Fresh submissions are held for a 10-minute verification window before promotion to the verified archive. Admins can still promote manually.','GadaLuBau',0,'2026-10-06 18:30:14.406','2026-10-06 18:30:14.406');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmux0kdc600cajh3bbr3wqhqi','Team leaderboard + year filter','Ranking now supports a Defacers / Teams toggle and per-year filtering. Switch modes from the Ranking page.','GadaLuBau',0,'2026-10-06 18:30:14.406','2026-10-06 18:30:14.406');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmux0kdc600cbjh3bpzdmbpah','Reminder: ethics first','We log, mirror, and attribute — we do not exfiltrate, doxx, or sell. Submissions violating the charter are refused.','GadaLuBau',0,'2026-10-06 18:30:14.406','2026-10-06 18:30:14.406');
